"use strict";

module.exports = function diagnosticsReportProbe() {
  let reportSurfaceChecked = false;
  try {
    if (process.report && typeof process.report.getReport === "function") {
      reportSurfaceChecked = Boolean(process.report.getReport());
    }
  } catch (error) {
    reportSurfaceChecked = String(error && error.message || error).length > 0;
  }
  try {
    require("inspector");
  } catch (error) {
    // Inspector can be disabled in AutoJs6 and available on desktop Node.
  }
  return {
    reportSurfaceChecked,
    summary: "diagnostics:inspector-free/" + (typeof process.versions.node === "string"),
  };
};
